// Datos editables: productos de cada supermercado, ingredientes, platos, recetas y nutrición.
//
// Producto (Prod): nombre, marca, envase, unidades por envase, precio en €, estado del dato y fuente (último campo, solo si está contrastado):
//   1 = nombre y precio contrastados en la ficha del supermercado (MCP Supermercados: API de Mercadona y dia.es); la fuente y la fecha van en el último campo
//   2 = el producto existe (nombre contrastado), pero el precio es una estimación
//   0 = sin contrastar: nombre y precio estimados. La app los marca como "estimado" hasta que los confirmes en tienda.
// Si un ingrediente solo tiene producto en un supermercado (M = Mercadona, D = Día), los platos que lo usan solo
// aparecen cuando eliges ese supermercado.
// k = [kcal, proteína, hidratos, grasa] por 100 g (o 100 ml) según la ficha; f = foto: 'm:<archivo>' (Mercadona) o 'd:<sku>' (Día). Sin k, el dato no consta en la ficha.
export type Prod = { n: string; b: string; pk: string; q: number; p: number; v: number; s?: string; k?: number[]; f?: string };
// Ingrediente: nombre, zona (C congelado, F frío, E estante), unidad, días que aguanta (life) y si cuentan desde que
// se abre (open = 1) o desde la compra (open = 0), gramos por unidad (gu, para las unidades que no son g o ml) y
// etiquetas de dieta (t): carne, embutido, pescado, lacteo, gluten, harina, huevo, frutoseco.
export type Ing = { n: string; s: 'C' | 'F' | 'E'; u: string; life: number; open: number; gu?: number; t?: string; M?: Prod; D?: Prod };
// Meal: [nombre, etiquetas, minutos de cocina, [[ingrediente, cantidad]], [kcal, prot, hidratos, grasa, fibra], pasos separados por |, utensilios, segundos de temporizador, 'L'=legumbre]
//   etiquetas: 'R' = apto para días de resfriado (caliente, con vitamina C o reconfortante).
//   minutos de cocina: sin contar sacar, pesar y recoger; la app suma ese tiempo sola (ver prep() en logic.ts).
//   La nutrición se recalcula desde los productos con: npx tsx tools/nutricion.ts --aplicar
export type Meal = [string, string, number, [string, number][], number[], string, string, number, string?];
const P = (n: string, b: string, pk: string, q: number, p: number, v = 0, s = '', k?: number[], f?: string): Prod => ({ n, b, pk, q, p, v, s, ...(k ? { k } : {}), ...(f ? { f } : {}) });
// URL de la foto de un producto (px = lado en píxeles).
export const fotoUrl = (p: Prod, px = 300): string => !p.f ? '' : p.f[0] === 'm' ? `https://prod-mercadona.imgix.net/images/${p.f.slice(2)}?fit=crop&h=${px}&w=${px}` : `https://www.dia.es/product_images/${p.f.slice(2)}/${p.f.slice(2)}_ISO_0_ES.jpg`;
export const DEF: number[][] = [[0, 0, 0, 0, -1, 0], [1, 2, 2, 1, -1, 1], [3, 3, 1, 2, -1, 2], [4, 1, 3, 3, -1, 3], [2, 4, 4, 4, -1, 0], [0, 5, 0, 3, -1, 1], [1, 6, 5, 1, -1, 2]];

